#!/bin/sh
# GENERATED by `fabricx generate`. Attach the host-facing ports of leaf1 to their VLAN bridges.
# Runs after containerlab has wired the links (clab `exec`). That can happen before setup.sh (started by the
# container's own command) has built the bridges, so wait for each bridge, at most 30 s.
set -e
# --- host port eth3 -> h1
for i in $(seq 60); do ip link show br10 >/dev/null 2>&1 && break; sleep 0.5; done
ip link set eth3 master br10
ip link set eth3 up
# --- host port eth4 -> h2
for i in $(seq 60); do ip link show br20 >/dev/null 2>&1 && break; sleep 0.5; done
ip link set eth4 master br20
ip link set eth4 up
